#include <JuceHeader.h>
#include <atomic>
#include <thread>
#include <iostream>
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;if(argc<2)return 2;juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> descriptions;format.findAllTypesForFile(descriptions,argv[1]);if(descriptions.isEmpty()){std::cerr<<"VST3 scan failed\n";return 1;}juce::String error;auto plugin=format.createInstanceFromDescription(*descriptions[0],48000,256,error);if(!plugin){std::cerr<<error<<'\n';return 1;}if(argc>2)plugin->setCurrentProgram(juce::String(argv[2]).getIntValue());plugin->setPlayConfigDetails(2,2,48000,256);plugin->prepareToPlay(48000,256);std::atomic<bool> running{true};std::atomic<int> blocks{0};std::atomic<bool> finite{true};std::thread audio([&]{juce::AudioBuffer<float> buffer(2,256);juce::MidiBuffer midi;while(running){buffer.clear();buffer.setSample(0,0,.1f);buffer.setSample(1,0,.1f);plugin->processBlock(buffer,midi);for(int c=0;c<2;++c)for(int i=0;i<256;++i)if(!std::isfinite(buffer.getSample(c,i)))finite=false;++blocks;std::this_thread::sleep_for(std::chrono::milliseconds(1));}});
 for(int cycle=0;cycle<30;++cycle){std::unique_ptr<juce::AudioProcessorEditor> editor(plugin->createEditorIfNeeded());if(!editor){finite=false;break;}editor->addToDesktop(juce::ComponentPeer::windowIsTemporary);editor->setVisible(true);juce::MessageManager::getInstance()->runDispatchLoopUntil(10);editor->setSize(cycle%2?843:1124,cycle%2?585:780);for(auto* p:plugin->getParameters())if(p->getName(100)=="Time ms")p->setValueNotifyingHost(float(cycle%10)/10);editor.reset();juce::MessageManager::getInstance()->runDispatchLoopUntil(5);}
 running=false;audio.join();juce::MemoryBlock state;plugin->getStateInformation(state);plugin->setStateInformation(state.getData(),int(state.getSize()));plugin->releaseResources();if(!finite){std::cerr<<"Hosted audio/editor check failed\n";return 1;}std::cout<<"PASS: actual VST3 scanned and loaded; 30 native editor open/resize/close cycles while audio processed "<<blocks<<" blocks; state roundtrip\n";}
